const isPointInPolygon = (x: number, y: number, polygon: { x: number; y: number }[]) => {
  let inside = false;
  for (let i = 0, j = polygon.length - 1; i < polygon.length; j = i++) {
    const xi = polygon[i].x, yi = polygon[i].y;
    const xj = polygon[j].x, yj = polygon[j].y;
    const intersect = ((yi > y) !== (yj > y))
        && (x < (xj - xi) * (y - yi) / (yj - yi) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
};

const getPolygonCentroid = (polygon: { x: number; y: number }[]) => {
  if (!polygon || polygon.length === 0) return null;
  let sumX = 0;
  let sumY = 0;
  polygon.forEach(pt => {
    sumX += pt.x;
    sumY += pt.y;
  });
  return {
    x: sumX / polygon.length,
    y: sumY / polygon.length
  };
};

const getPolygonArea = (polygon: { x: number; y: number }[]) => {
  if (!polygon || polygon.length < 3) return 0;
  let area = 0;
  for (let i = 0; i < polygon.length; i++) {
    const j = (i + 1) % polygon.length;
    area += polygon[i].x * polygon[j].y;
    area -= polygon[j].x * polygon[i].y;
  }
  return Math.abs(area) / 2;
};

export default function MotorcycleDamageSelector({
  damagePoints,
  onChange,
  readOnly = false,
}: MotorcycleDamageSelectorProps) {
  const renderStyle = "solid";
  const [perspective, setPerspective] = useState<"left" | "right" | "front" | "rear" | "top">("left");
  const [activeHotspot, setActiveHotspot] = useState<Hotspot2D | null>(null);
  const [damageType, setDamageType] = useState<"riscado" | "quebrado">("riscado");
  const [description, setDescription] = useState("");
  const [partNameInput, setPartNameInput] = useState("");
  const [isCalibrating, setIsCalibrating] = useState(false);
  const [calibrationData, setCalibrationData] = useState<Record<string, Hotspot2D[]>>(HOTSPOTS_BY_PERSPECTIVE);
  const [calibrationActiveIndex, setCalibrationActiveIndex] = useState(0);
  const [currentPath, setCurrentPath] = useState<{ x: number; y: number }[]>([]);
  const [newCustomPartName, setNewCustomPartName] = useState("");
  const [activeLightboxPhoto, setActiveLightboxPhoto] = useState<string | null>(null);
  const [activeDropdown, setActiveDropdown] = useState<string | null>(null);

  const handleCapturePhoto = async (partId: string) => {
    try {
      const { Camera, CameraResultType, CameraSource } = await import('@capacitor/camera');
      const image = await Camera.getPhoto({
        quality: 90,
        allowEditing: false,
        resultType: CameraResultType.Base64,
        source: CameraSource.Camera,
        saveToGallery: false,
      });
      if (image.base64String) {
        const photoUrl = `data:image/jpeg;base64,${image.base64String}`;
        const updated = damagePoints.map(p =>
          p.partId === partId ? { ...p, photo: photoUrl } : p
        );
        onChange(updated);
      }
    } catch (error) {
      console.error("Erro ao capturar foto com Capacitor Camera, tentando fallback HTML5:", error);
      try {
        const input = document.createElement("input");
        input.type = "file";
        input.accept = "image/*";
        input.setAttribute("capture", "environment");
        
        input.onchange = (e: any) => {
          const file = e.target.files?.[0];
          if (file) {
            const reader = new FileReader();
            reader.onload = (event) => {
              if (event.target?.result) {
                const photoUrl = event.target.result as string;
                const updated = damagePoints.map(p =>
                  p.partId === partId ? { ...p, photo: photoUrl } : p
                );
                onChange(updated);
              }
            };
            reader.readAsDataURL(file);
          }
        };
        input.click();
      } catch (fallbackError) {
        console.error("Fallback HTML5 Camera falhou:", fallbackError);
      }
    } finally {
      setActiveDropdown(null);
    }
  };

  // States for freehand pencil drawing
  const [isDrawing, setIsDrawing] = useState(false);
  const [hasDragged, setHasDragged] = useState(false);
  const [dragStartPoint, setDragStartPoint] = useState<{ x: number; y: number } | null>(null);

  const [zoomLevel, setZoomLevel] = useState(1);
  const [panOffset, setPanOffset] = useState({ x: 0, y: 0 });
  const [isPinching, setIsPinching] = useState(false);
  const lastPinchDistance = useRef<number | null>(null);
  const lastPanPoint = useRef<{ x: number; y: number } | null>(null);
  const zoomContainerRef = useRef<HTMLDivElement>(null);
  const [isFullscreen, setIsFullscreen] = useState(false);

  const handlePinchStart = useCallback((e: React.TouchEvent) => {
    if (e.touches.length === 2) {
      e.preventDefault();
      setIsPinching(true);
      const dx = e.touches[0].clientX - e.touches[1].clientX;
      const dy = e.touches[0].clientY - e.touches[1].clientY;
      lastPinchDistance.current = Math.hypot(dx, dy);
      const mx = (e.touches[0].clientX + e.touches[1].clientX) / 2;
      const my = (e.touches[0].clientY + e.touches[1].clientY) / 2;
      lastPanPoint.current = { x: mx, y: my };
    }
  }, []);

  const handlePinchMove = useCallback((e: React.TouchEvent) => {
    if (e.touches.length === 2 && lastPinchDistance.current !== null) {
      e.preventDefault();
      const dx = e.touches[0].clientX - e.touches[1].clientX;
      const dy = e.touches[0].clientY - e.touches[1].clientY;
      const dist = Math.hypot(dx, dy);
      const scale = dist / lastPinchDistance.current;
      setZoomLevel(prev => Math.min(4, Math.max(1, prev * scale)));
      lastPinchDistance.current = dist;

      // Pan while pinching
      const mx = (e.touches[0].clientX + e.touches[1].clientX) / 2;
      const my = (e.touches[0].clientY + e.touches[1].clientY) / 2;
      if (lastPanPoint.current) {
        const deltaX = mx - lastPanPoint.current.x;
        const deltaY = my - lastPanPoint.current.y;
        setPanOffset(prev => ({ x: prev.x + deltaX, y: prev.y + deltaY }));
      }
      lastPanPoint.current = { x: mx, y: my };
    } else if (e.touches.length === 1 && zoomLevel > 1 && !isDrawing) {
      // Single finger pan when zoomed
      e.preventDefault();
      const touch = e.touches[0];
      if (lastPanPoint.current) {
        const deltaX = touch.clientX - lastPanPoint.current.x;
        const deltaY = touch.clientY - lastPanPoint.current.y;
        setPanOffset(prev => ({ x: prev.x + deltaX, y: prev.y + deltaY }));
      }
      lastPanPoint.current = { x: touch.clientX, y: touch.clientY };
    }
  }, [zoomLevel, isDrawing]);

  const handlePinchEnd = useCallback(() => {
    setIsPinching(false);
    lastPinchDistance.current = null;
    lastPanPoint.current = null;
    // Snap back to 1x if barely zoomed
    setZoomLevel(prev => {
      if (prev < 1.15) {
        setPanOffset({ x: 0, y: 0 });
        return 1;
      }
      return prev;
    });
  }, []);

  const resetZoom = useCallback(() => {
    setZoomLevel(1);
    setPanOffset({ x: 0, y: 0 });
  }, []);

  const handleSavePolygon = () => {
    if (currentPath.length < 3) {
      toast.error("Desenhe pelo menos 3 pontos para formar um polígono.");
      return;
    }
    const currentList = calibrationData[perspective] || [];
    const updatedList = currentList.map((h, i) => {
      if (i === calibrationActiveIndex) {
        return {
          ...h,
          polygon: currentPath,
          left: undefined,
          top: undefined
        };
      }
      return h;
    });
    setCalibrationData({
      ...calibrationData,
      [perspective]: updatedList
    });
    setCurrentPath([]);
    if (calibrationActiveIndex < currentList.length - 1) {
      setCalibrationActiveIndex(calibrationActiveIndex + 1);
    }
    toast.success("Área salva com sucesso!");
  };

  const handleClearDrawing = () => {
    setCurrentPath([]);
    const currentList = calibrationData[perspective] || [];
    const updatedList = currentList.map((h, i) => {
      if (i === calibrationActiveIndex) {
        return {
          ...h,
          polygon: undefined,
          left: undefined,
          top: undefined
        };
      }
      return h;
    });
    setCalibrationData({
      ...calibrationData,
      [perspective]: updatedList
    });
    toast.success("Área e desenho limpos.");
  };

  const handleAddCustomPartToCalibrate = () => {
    if (!newCustomPartName.trim()) return;
    const newId = `custom_part_${Date.now()}`;
    const newPart: Hotspot2D = {
      id: newId,
      name: newCustomPartName.trim(),
    };
    const currentList = calibrationData[perspective] || [];
    const updatedData = {
      ...calibrationData,
      [perspective]: [...currentList, newPart]
    };
    setCalibrationData(updatedData);
    setCalibrationActiveIndex(currentList.length); 
    setCurrentPath([]);
    setNewCustomPartName("");
    toast.success(`Peça "${newPart.name}" adicionada à calibração!`);
  };

  // Helper to retrieve displaying coordinates (x, y) and perspective for a point (with fallback support)
  const getPointDisplayInfo = (point: DamagePoint) => {
    if (point.x !== undefined && point.y !== undefined && point.perspective) {
      return {
        x: point.x,
        y: point.y,
        perspective: point.perspective,
      };
    }
    // Fallback to searching predefined hotspots
    for (const [pKey, list] of Object.entries(calibrationData)) {
      const match = list.find((h) => h.id === point.partId);
      if (match) {
        let xVal = 0;
        let yVal = 0;
        if (match.polygon && match.polygon.length > 0) {
          const ctr = getPolygonCentroid(match.polygon);
          if (ctr) {
            xVal = ctr.x;
            yVal = ctr.y;
          }
        } else if (match.left && match.top) {
          xVal = parseFloat(match.left);
          yVal = parseFloat(match.top);
        } else {
          continue;
        }
        return {
          x: xVal,
          y: yVal,
          perspective: pKey,
        };
      }
    }
    return null;
  };

  // Coordinates helper mapping pointer/touch Client relative coordinates
  const getRelativeCoordinates = (clientX: number, clientY: number, currentTarget: HTMLDivElement) => {
    const rect = currentTarget.getBoundingClientRect();
    const x = ((clientX - rect.left) / rect.width) * 100;
    const y = ((clientY - rect.top) / rect.height) * 100;
    return { x, y };
  };

  // Drag-to-Draw (Freehand Pencil) event handlers
  const handleMouseDown = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!isCalibrating || readOnly) return;
    const target = e.target as HTMLElement;
    if (target.closest("button") || target.closest("input") || target.closest("label")) {
      return;
    }
    const { x, y } = getRelativeCoordinates(e.clientX, e.clientY, e.currentTarget);
    setIsDrawing(true);
    setHasDragged(false);
    setDragStartPoint({ x, y });
  };

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!isCalibrating || !isDrawing || !dragStartPoint || readOnly) return;
    const { x, y } = getRelativeCoordinates(e.clientX, e.clientY, e.currentTarget);
    const lastPt = hasDragged && currentPath.length > 0 ? currentPath[currentPath.length - 1] : dragStartPoint;
    const dist = Math.hypot(x - lastPt.x, y - lastPt.y);
    
    // Smooth threshold (only add point if mouse dragged far enough from the last point)
    if (dist > 0.8) {
      if (!hasDragged) {
        setHasDragged(true);
        setCurrentPath([dragStartPoint, { x, y }]);
      } else {
        setCurrentPath((prev) => [...prev, { x, y }]);
      }
    }
  };

  const handleMouseUp = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!isCalibrating || !isDrawing || readOnly) return;
    setIsDrawing(false);
    if (!hasDragged && dragStartPoint) {
      // Single click behavior: append point to existing path
      setCurrentPath((prev) => [...prev, dragStartPoint]);
    }
    setDragStartPoint(null);
  };

  const handleMouseLeave = () => {
    if (!isCalibrating || !isDrawing || readOnly) return;
    setIsDrawing(false);
    if (!hasDragged && dragStartPoint) {
      setCurrentPath((prev) => [...prev, dragStartPoint]);
    }
    setDragStartPoint(null);
  };

  // Touch drawing support for mobile/tablet devices
  const handleTouchStart = (e: React.TouchEvent<HTMLDivElement>) => {
    if (!isCalibrating || readOnly || e.touches.length === 0) return;
    const touch = e.touches[0];
    const { x, y } = getRelativeCoordinates(touch.clientX, touch.clientY, e.currentTarget);
    setIsDrawing(true);
    setHasDragged(false);
    setDragStartPoint({ x, y });
  };

  const handleTouchMove = (e: React.TouchEvent<HTMLDivElement>) => {
    if (!isCalibrating || !isDrawing || !dragStartPoint || readOnly || e.touches.length === 0) return;
    // Disable page scrolling while drawing
    if (e.cancelable) e.preventDefault();
    const touch = e.touches[0];
    const { x, y } = getRelativeCoordinates(touch.clientX, touch.clientY, e.currentTarget);
    const lastPt = hasDragged && currentPath.length > 0 ? currentPath[currentPath.length - 1] : dragStartPoint;
    const dist = Math.hypot(x - lastPt.x, y - lastPt.y);

    if (dist > 0.8) {
      if (!hasDragged) {
        setHasDragged(true);
        setCurrentPath([dragStartPoint, { x, y }]);
      } else {
        setCurrentPath((prev) => [...prev, { x, y }]);
      }
    }
  };

  const handleTouchEnd = (e: React.TouchEvent<HTMLDivElement>) => {
    if (!isCalibrating || !isDrawing || readOnly) return;
    setIsDrawing(false);
    if (!hasDragged && dragStartPoint) {
      setCurrentPath((prev) => [...prev, dragStartPoint]);
    }
    setDragStartPoint(null);
  };

  const handleContainerClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (readOnly) return;

    // Do nothing if the click is on an interactive element inside the container
    const target = e.target as HTMLElement;
    if (target.closest("button") || target.closest("input") || target.closest("label")) {
      return;
    }

    // Ignore normal clicks if calibrating since drawing events handle it
    if (isCalibrating) return;

    const rect = e.currentTarget.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width) * 100;
    const y = ((e.clientY - rect.top) / rect.height) * 100;

    // Find if click falls inside any predefined polygon (prioritize smaller overlapping areas)
    let matchedHotspot: Hotspot2D | null = null;
    const hotspots = calibrationData[perspective] || [];
    const polygonMatches: { hotspot: Hotspot2D; area: number }[] = [];
    for (const h of hotspots) {
      if (h.polygon && h.polygon.length >= 3) {
        if (isPointInPolygon(x, y, h.polygon)) {
          polygonMatches.push({
            hotspot: h,
            area: getPolygonArea(h.polygon)
          });
        } 
      }
    }
    if (polygonMatches.length > 0) {
      polygonMatches.sort((a, b) => a.area - b.area);
      matchedHotspot = polygonMatches[0].hotspot;
    }

    // Fallback: closest centroid or top/left
    if (!matchedHotspot) {
      let minDistance = Infinity;
      for (const h of hotspots) {
        let hX = 0;
        let hY = 0;
        if (h.polygon && h.polygon.length > 0) {
          const ctr = getPolygonCentroid(h.polygon);
          if (ctr) {
            hX = ctr.x;
            hY = ctr.y;
          }
        } else if (h.left && h.top) {
          hX = parseFloat(h.left);
          hY = parseFloat(h.top);
        } else {
          continue;
        }
        const dist = Math.hypot(hX - x, hY - y);
        if (dist < minDistance) {
          minDistance = dist;
          matchedHotspot = h;
        }
      }
    }

    const suggestedName = (matchedHotspot ? matchedHotspot.name : `Ponto na lateral ${perspective}`).toUpperCase();
    const tempId = `dmg_${Date.now()}`;

    setPartNameInput(suggestedName);
    setDamageType("riscado");
    setDescription("");
    setActiveHotspot({
      id: tempId,
      name: suggestedName,
      left: `${x.toFixed(1)}%`,
      top: `${y.toFixed(1)}%`,
    });
  };

  const handleSaveDamage = () => {
    if (!activeHotspot || readOnly) return;

    const filtered = damagePoints.filter((p) => p.partId !== activeHotspot.id);
    
    // Parse coordinates from activeHotspot properties
    const xVal = activeHotspot.left ? parseFloat(activeHotspot.left) : undefined;
    const yVal = activeHotspot.top ? parseFloat(activeHotspot.top) : undefined;

    const updated = [
      ...filtered,
      {
        partId: activeHotspot.id,
        partName: partNameInput.trim() || activeHotspot.name,
        type: damageType,
        description: description.trim() || undefined,
        x: xVal,
        y: yVal,
        perspective: perspective,
      },
    ];

    onChange(updated);
    setActiveHotspot(null);
    setDescription("");
  };

  const handleRemoveDamage = (partId: string) => {
    if (readOnly) return;
    const updated = damagePoints.filter((p) => p.partId !== partId);
    onChange(updated);
    if (activeHotspot?.id === partId) {
      setActiveHotspot(null);
    }
  };

  // Find which perspective is best suited to show a specific part
  const handleSelectDamageFromList = (partId: string) => {
    const point = damagePoints.find(p => p.partId === partId);
    if (!point) return;

    const info = getPointDisplayInfo(point);
    if (info) {
      setPerspective(info.perspective as any);
      setPartNameInput(point.partName.toUpperCase());
      setDamageType(point.type);
      setDescription(point.description || "");
      setActiveHotspot({
        id: point.partId,
        name: point.partName,
        left: `${info.x}%`,
        top: `${info.y}%`
      });
    }
  };

  // Generate SVG styles based on the active renderStyle (solid black, blue x-ray, cyan hologram)
  const getStyleClasses = () => {
    return {
      background: "bg-white",
      stroke: "stroke-zinc-800",
      strokeWidth: "2",
      fillMain: "fill-zinc-800",
      fillSecondary: "fill-zinc-700",
      fillAccent: "fill-zinc-900",
      fillFrame: "fill-zinc-600",
      fillGlass: "fill-zinc-550/20",
      fillTire: "fill-zinc-900",
      textColor: "text-zinc-800",
    };
  };

  const sc = getStyleClasses();

  // Helper to render the premium 2D vector schematic based on perspective
  // Helper to render real motorcycle images based on perspective
  const renderMotorcycleImage = () => {
    let imgPath = "";
    switch (perspective) {
      case "left":
        imgPath = "/modelo-moto-vistoria/scramber400xc-lado-esquerdo.jpg";
        break;
      case "right":
        imgPath = "/modelo-moto-vistoria/scramber400xc-lado-direito.jpg";
        break;
      case "front":
        imgPath = "/modelo-moto-vistoria/scramber400xc-lado-frente.jpg";
        break;
      case "rear":
        imgPath = "/modelo-moto-vistoria/scramber400xc-lado-tras.jpg";
        break;
      case "top":
        imgPath = "/modelo-moto-vistoria/scramber400xc-lado-topo.jpg";
        break;
    }
    return (
      <img
        src={imgPath}
        alt={`Perspectiva ${perspective}`}
        className="w-full h-full object-contain select-none pointer-events-none rounded-xl"
      />
    );
  };

  return (
    <>
    <div className="space-y-6">
      {/* Visual Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-zinc-100 pb-4">
        <div>
          <h3 className="text-sm font-bold text-zinc-900 flex items-center gap-2">
            <Wrench className="h-4 w-4 text-zinc-500" />
            Mapeamento Visual de Avarias
            <span className="hidden sm:inline-flex text-[9px] font-extrabold bg-zinc-50 border border-zinc-200 text-zinc-600 px-1.5 py-0.5 rounded tracking-widest uppercase">
              Foto Real Multi-Perspectiva
            </span>
          </h3>
          <p className="text-xs text-zinc-500 mt-1 font-semibold">
            {readOnly 
              ? "Mapeamento de avarias estéticas/estruturais registradas na vistoria." 
              : "Escolha a perspectiva e clique na foto para registrar a avaria no local exato."}
          </p>
        </div>

        {/* Legend status indicators & Calibration mode toggle */}
        <div className="flex items-center gap-4 text-xs font-semibold select-none">
          <div className="flex items-center gap-1.5">
            <span className="h-3 w-3 rounded-full bg-amber-500 border border-amber-400 shadow-[0_0_6px_#f59e0b] animate-pulse" />
            <span className="text-zinc-500">Riscado</span>
          </div>
          <div className="flex items-center gap-1.5">
            <span className="h-3 w-3 rounded-full bg-red-500 border border-red-400 shadow-[0_0_6px_#ef4444] animate-ping" style={{ animationDuration: '1.5s' }} />
            <span className="text-zinc-500">Quebrado</span>
          </div>
          {!readOnly && (
            <button
              type="button"
              onClick={() => {
                setIsCalibrating(!isCalibrating);
                setCalibrationActiveIndex(0);
              }}
              className={`ml-2 px-2.5 py-1 rounded-lg border text-[10px] font-extrabold uppercase tracking-wide transition-all cursor-pointer ${
                isCalibrating 
                  ? "bg-purple-600 border-purple-500 text-white shadow-sm shadow-purple-500/50"
                  : "bg-white border-zinc-200 text-zinc-600 hover:bg-zinc-50"
              }`}
            >
              ⚙️ Calibrar
            </button>
          )}
        </div>
      </div>

      {isCalibrating && (
        <div className="bg-purple-50 border border-purple-200 rounded-2xl p-4 text-purple-950 space-y-3 animate-fade-in print:hidden">
          <div className="flex justify-between items-center">
            <h4 className="text-xs font-bold uppercase tracking-wider flex items-center gap-1.5">
              <span>🔧 Calibração Visual por Desenho de Área (Polígonos)</span>
            </h4>
            <button
              type="button"
              onClick={() => {
                setIsCalibrating(false);
                setCurrentPath([]);
              }}
              className="text-xs bg-purple-900 text-white font-bold rounded-lg px-2.5 py-1 hover:bg-purple-800 cursor-pointer"
            >
              Sair do Modo Calibração
            </button>
          </div>

          <div className="text-xs space-y-1 font-semibold">
            <p>
              Como desenhar a área de cada peça na foto:
            </p>
            <ol className="list-decimal pl-4 space-y-0.5 text-purple-800 text-[11px]">
              <li>Selecione a peça ativa na lista abaixo.</li>
              <li><strong>Desenho Livre (Lápis):</strong> Clique e arraste o mouse/dedo ao redor da peça na foto para traçar o contorno de forma contínua.</li>
              <li><strong>Clique a Clique:</strong> Se preferir, dê cliques pontuais ao redor da peça para traçar os vértices um a um.</li>
              <li>Após cobrir a peça por completo com o contorno, clique em <strong className="text-purple-950">"Confirmar Área"</strong> para salvá-lo.</li>
            </ol>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {/* Hotspots list */}
            <div className="md:col-span-2 flex flex-col space-y-2">
              <div className="border border-purple-200 bg-white rounded-xl p-2.5 max-h-[180px] overflow-y-auto space-y-1">
                {(calibrationData[perspective] || []).map((h, i) => {
                  const isActive = i === calibrationActiveIndex;
                  const hasArea = h.polygon && h.polygon.length >= 3;
                  const pointsCount = h.polygon ? h.polygon.length : 0;
                  return (
                    <button
                      key={h.id}
                      type="button"
                      onClick={() => {
                        setCalibrationActiveIndex(i);
                        setCurrentPath([]);
                      }}
                      className={`w-full text-left px-2 py-1 rounded text-xs font-bold flex justify-between items-center transition-colors ${
                        isActive 
                          ? "bg-purple-600 text-white" 
                          : "hover:bg-purple-100 text-purple-900"
                      }`}
                    >
                      <span>{i + 1}. {h.name}</span>
                      <span className="text-[10px] opacity-75 font-semibold">
                        {hasArea ? `🟢 ${pointsCount} pontos (Área Definida)` : "⚪ Não desenhado"}
                      </span>
                    </button>
                  );
                })}
              </div>

              {/* Add custom part input */}
              <div className="flex items-center gap-1.5 pt-1">
                <input
                  type="text"
                  placeholder="Nome de outra peça para adicionar..."
                  value={newCustomPartName}
                  onChange={(e) => setNewCustomPartName(e.target.value)}
                  className="flex-1 bg-white border border-purple-200 rounded-lg px-2.5 py-1 text-xs text-zinc-700 placeholder-zinc-400 focus:outline-none focus:border-purple-500 font-semibold"
                />
                <button
                  type="button"
                  onClick={handleAddCustomPartToCalibrate}
                  className="bg-purple-900 hover:bg-purple-800 text-white rounded-lg px-3 py-1 text-xs font-bold transition-colors cursor-pointer shrink-0"
                >
                  + Add Peça
                </button>
              </div>
            </div>

            {/* Actions & JSON output */}
            <div className="flex flex-col justify-between space-y-2">
              <div className="space-y-1.5">
                <div className="flex gap-2">
                  <button
                    type="button"
                    disabled={calibrationActiveIndex === 0}
                    onClick={() => {
                      setCalibrationActiveIndex(calibrationActiveIndex - 1);
                      setCurrentPath([]);
                    }}
                    className="flex-1 bg-purple-100 hover:bg-purple-200 disabled:opacity-40 text-purple-950 font-bold text-xs rounded-lg py-1.5 cursor-pointer text-center"
                  >
                    Anterior
                  </button>
                  <button
                    type="button"
                    disabled={calibrationActiveIndex >= (calibrationData[perspective] || []).length - 1}
                    onClick={() => {
                      setCalibrationActiveIndex(calibrationActiveIndex + 1);
                      setCurrentPath([]);
                    }}
                    className="flex-1 bg-purple-100 hover:bg-purple-200 disabled:opacity-40 text-purple-950 font-bold text-xs rounded-lg py-1.5 cursor-pointer text-center"
                  >
                    Próximo
                  </button>
                </div>

                <div className="flex gap-2">
                  <button
                    type="button"
                    onClick={handleSavePolygon}
                    className="flex-1 bg-emerald-600 hover:bg-emerald-500 text-white font-extrabold text-xs rounded-lg py-2 cursor-pointer text-center shadow"
                  >
                    💾 Confirmar Área
                  </button>
                  <button
                    type="button"
                    onClick={handleClearDrawing}
                    className="flex-1 bg-red-100 hover:bg-red-200 text-red-700 font-bold text-xs rounded-lg py-2 cursor-pointer text-center"
                  >
                    🗑️ Limpar
                  </button>
                </div>
              </div>

              <button
                type="button"
                onClick={() => {
                  navigator.clipboard.writeText(JSON.stringify(calibrationData, null, 2));
                  toast.success("JSON de Calibração copiado para a área de transferência!");
                }}
                className="w-full bg-purple-900 hover:bg-purple-800 text-white font-bold text-xs rounded-lg py-2 cursor-pointer text-center"
              >
                Copiar JSON de Calibração
              </button>

              <div className="text-[9px] text-purple-700 italic leading-tight">
                Dica: Calibre os contornos das peças em todas as perspectivas e depois copie o JSON completo para nos enviar!
              </div>
            </div>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 items-start print:grid-cols-1 print:gap-6 print:break-inside-avoid">
        
        {/* Canvas Area Container */}
        {!isFullscreen ? (
          <div className="lg:col-span-2 relative overflow-hidden flex flex-col justify-between print:border-none print:shadow-none print:bg-transparent print:col-span-1">

          {/* Mobile zoom indicator & reset */}
          {zoomLevel > 1 && (
            <div className="sm:hidden absolute top-12 right-3 z-40 flex items-center gap-1.5 animate-fade-in">
              <span className="text-[10px] font-extrabold text-zinc-500 bg-white/90 backdrop-blur-sm border border-zinc-200 px-2 py-0.5 rounded-md shadow-sm">
                {Math.round(zoomLevel * 100)}%
              </span>
              <button
                type="button"
                onClick={resetZoom}
                className="p-1 bg-white/90 backdrop-blur-sm border border-zinc-200 text-zinc-600 hover:text-zinc-900 rounded-md shadow-sm"
              >
                <RotateCcw className="h-3 w-3" />
              </button>
            </div>
          )}
          
          {/* Quick HUD controls overlay (Top Header Inside Canvas) */}
          <div className="absolute top-3 left-3 right-3 z-30 flex items-center justify-between pointer-events-none print:hidden">
            
            {/* View presets */}
            <div className="flex gap-1 bg-white/90 backdrop-blur-sm border border-zinc-200 p-1 rounded-lg pointer-events-auto shadow-sm">
              {[
                { key: "left", label: "Esq" },
                { key: "right", label: "Dir" },
                { key: "front", label: "Front" },
                { key: "rear", label: "Tras" },
                { key: "top", label: "Topo" },
              ].map((view) => (
                <button
                  key={view.key}
                  type="button"
                  onClick={() => {
                    setPerspective(view.key as any);
                    setActiveHotspot(null);
                    resetZoom();
                  }}
                  className={`px-2.5 py-1 text-[11px] font-bold rounded transition-all ${
                    perspective === view.key
                      ? "bg-zinc-900 text-white shadow-sm"
                      : "text-zinc-500 hover:text-zinc-950 hover:bg-zinc-100"
                  }`}
                >
                  {view.label}
                </button>
              ))}
            </div>

            {/* Reset selection / view */}
            <div className="flex gap-1.5 pointer-events-auto">
              <button
                type="button"
                onClick={() => {
                  setPerspective("left");
                  setActiveHotspot(null);
                  resetZoom();
                }}
                className="p-1.5 bg-white/90 backdrop-blur-sm border border-zinc-200 hover:border-zinc-350 text-zinc-500 hover:text-zinc-800 rounded-lg transition-colors shadow-sm"
                title="Voltar ao Padrão (Esq)"
              >
                <RotateCcw className="h-4 w-4" />
              </button>
              
              <button
                type="button"
                onClick={() => setIsFullscreen(true)}
                className="p-1.5 bg-white/90 backdrop-blur-sm border border-zinc-200 hover:border-zinc-350 text-zinc-500 hover:text-zinc-800 rounded-lg transition-colors shadow-sm flex items-center justify-center"
                title="Abrir em Tela Cheia"
              >
                <Maximize2 className="h-4 w-4" />
              </button>
            </div>
          </div>

          {/* Interactive Tutorial Tip */}
          <div className="absolute top-16 left-1/2 -translate-x-1/2 z-20 pointer-events-none text-center bg-white/70 border border-zinc-200/50 px-3.5 py-1 rounded-full text-[10px] font-bold text-zinc-500 tracking-wide backdrop-blur-[1px] opacity-80 print:hidden">
            {readOnly ? "Imagem Real da Moto" : "Clique na foto da moto para registrar a avaria no local exato"}
          </div>

          {/* 2D Schematic Interactive Area */}
          <div
            ref={zoomContainerRef}
            onTouchStart={(e) => {
              if (e.touches.length === 2) handlePinchStart(e);
              else if (e.touches.length === 1 && zoomLevel > 1) {
                lastPanPoint.current = { x: e.touches[0].clientX, y: e.touches[0].clientY };
              }
            }}
            onTouchMove={(e) => {
              if (e.touches.length >= 2 || (e.touches.length === 1 && zoomLevel > 1 && !isCalibrating)) {
                handlePinchMove(e);
              }
            }}
            onTouchEnd={handlePinchEnd}
            className={`w-full h-[360px] sm:h-[450px] flex items-center justify-center pt-12 pb-0 px-0 sm:p-8 rounded-2xl relative select-none transition-colors duration-300 print:h-[260px] print:p-0 print:border-none print:shadow-none print:bg-transparent ${sc.background}`}
          >
            
            {/* Render selected perspective Real Image + Hotspots Overlay */}
            <div 
              onClick={handleContainerClick}
              onMouseDown={handleMouseDown}
              onMouseMove={handleMouseMove}
              onMouseUp={handleMouseUp}
              onMouseLeave={handleMouseLeave}
              onTouchStart={handleTouchStart}
              onTouchMove={handleTouchMove}
              onTouchEnd={handleTouchEnd}
              style={{
                position: "relative",
                width: "auto",
                height: "auto",
                maxWidth: "100%",
                maxHeight: "100%",
                aspectRatio: "2624/1632",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                cursor: readOnly ? "default" : "crosshair",
                touchAction: (isCalibrating || zoomLevel > 1) ? "none" : "auto",
                transform: `scale(${zoomLevel}) translate(${panOffset.x / zoomLevel}px, ${panOffset.y / zoomLevel}px)`,
                transformOrigin: "center center",
                transition: isPinching ? "none" : "transform 0.2s ease-out",
              }}
              className={`transition-all duration-300 ${sc.textColor}`}
            >
              {renderMotorcycleImage()}

              {/* SVG overlay to render polygons during calibration or for debug */}
              <svg className="absolute inset-0 w-full h-full pointer-events-none z-20">
                {/* Render already saved polygons for all hotspots of the current perspective */}
                {(calibrationData[perspective] || []).map((h, i) => {
                  if (!h.polygon || h.polygon.length < 2) return null;
                  const pointsString = h.polygon.map(p => `${p.x}%,${p.y}%`).join(" ");
                  const isActive = i === calibrationActiveIndex && isCalibrating;
                  return (
                    <polygon
                      key={h.id}
                      points={pointsString}
                      fill={isActive ? "rgba(168, 85, 247, 0.25)" : "rgba(168, 85, 247, 0.08)"}
                      stroke={isActive ? "#a855f7" : "rgba(168, 85, 247, 0.4)"}
                      strokeWidth="1.5"
                    />
                  );
                })}

                {/* Render current path being drawn */}
                {isCalibrating && currentPath.length > 0 && (
                  <>
                    {/* Render as a closed polygon with semi-transparent fill if we have >= 3 points */}
                    {currentPath.length >= 3 ? (
                      <polygon
                        points={currentPath.map(p => `${p.x}%,${p.y}%`).join(" ")}
                        fill="rgba(168, 85, 247, 0.15)"
                        stroke="#a855f7"
                        strokeWidth="2"
                        strokeDasharray="4 4"
                      />
                    ) : (
                      <polyline
                        points={currentPath.map(p => `${p.x}%,${p.y}%`).join(" ")}
                        fill="none"
                        stroke="#a855f7"
                        strokeWidth="2"
                        strokeDasharray="4 4"
                      />
                    )}
                    {/* Render dots for path vertices (only if clicking point-by-point or few vertices to keep freehand drawing clean) */}
                    {(!hasDragged || currentPath.length < 15) && currentPath.map((pt, idx) => (
                      <circle
                        key={idx}
                        cx={`${pt.x}%`}
                        cy={`${pt.y}%`}
                        r="3.5"
                        fill="#a855f7"
                        stroke="#fff"
                        strokeWidth="1"
                      />
                    ))}
                  </>
                )}
              </svg>

              {/* If calibrating, render the current calibration pins or centroids */}
              {isCalibrating && (calibrationData[perspective] || []).map((h, i) => {
                let xVal = 0;
                let yVal = 0;
                if (h.polygon && h.polygon.length > 0) {
                  const ctr = getPolygonCentroid(h.polygon);
                  if (ctr) {
                    xVal = ctr.x;
                    yVal = ctr.y;
                  }
                } else if (h.left && h.top) {
                  xVal = parseFloat(h.left);
                  yVal = parseFloat(h.top);
                } else {
                  return null;
                }
                const isActive = i === calibrationActiveIndex;
                return (
                  <div
                    key={h.id}
                    style={{ top: `${yVal}%`, left: `${xVal}%` }}
                    className="absolute -translate-x-1/2 -translate-y-1/2 z-20 pointer-events-none"
                  >
                    <div className={`h-4 w-4 rounded-full flex items-center justify-center text-[8px] font-bold text-white shadow ${
                      isActive ? "bg-purple-600 ring-2 ring-purple-300 scale-125" : "bg-purple-400 opacity-60"
                    }`}>
                      {i + 1}
                    </div>
                  </div>
                );
              })}

              {/* Clickable 2D Hotspots Overlay */}
              {(() => {
                // Show pending point if not saved yet
                const pendingPoint = activeHotspot && !damagePoints.some(d => d.partId === activeHotspot.id) ? {
                  partId: activeHotspot.id,
                  partName: partNameInput || activeHotspot.name,
                  type: damageType,
                  description: description,
                  x: activeHotspot.left ? parseFloat(activeHotspot.left) : 0,
                  y: activeHotspot.top ? parseFloat(activeHotspot.top) : 0,
                  perspective: perspective,
                  isPending: true
                } : null;

                const displayPoints: (DamagePoint & { x: number; y: number; perspective: string; isPending?: boolean })[] = damagePoints
                  .map(p => {
                    const info = getPointDisplayInfo(p);
                    if (!info) return null;
                    return {
                      ...p,
                      x: info.x,
                      y: info.y,
                      perspective: info.perspective,
                      isPending: false
                    };
                  })
                  .filter((p): p is NonNullable<typeof p> => p !== null && p.perspective === perspective);

                if (pendingPoint) {
                  displayPoints.push(pendingPoint as any);
                }

                return displayPoints.map((point) => {
                  const isActive = activeHotspot?.id === point.partId;
                  
                  // Determine color class based on registered/pending damage type
                  let colorClass = "bg-blue-500 border-blue-200 text-white shadow-blue-500/50 hover:bg-blue-600 hover:scale-110";
                  let animationClass = "";

                  if (point.isPending) {
                    colorClass = "bg-zinc-650 border-zinc-450 text-white shadow-zinc-500/50 hover:scale-110 animate-pulse";
                    animationClass = "animate-ping";
                  } else if (point.type === "quebrado") {
                    colorClass = "bg-red-500 border-red-300 text-white shadow-red-500/80 hover:bg-red-600 animate-pulse scale-110";
                    animationClass = "animate-ping";
                  } else if (point.type === "riscado") {
                    colorClass = "bg-amber-500 border-amber-300 text-white shadow-amber-500/80 hover:bg-amber-600 hover:scale-110 scale-105";
                    animationClass = "animate-pulse";
                  }

                  return (
                    <div
                      key={point.partId}
                      style={{ top: `${point.y}%`, left: `${point.x}%` }}
                      className="absolute -translate-x-1/2 -translate-y-1/2 z-10 animate-fade-in"
                    >
                      {/* Pulsing halo ring */}
                      <div className={`absolute -inset-2.5 rounded-full border border-current opacity-40 pointer-events-none scale-100 ${animationClass} ${
                        point.isPending 
                          ? "text-zinc-500"
                          : point.type === "quebrado" 
                            ? "text-red-500" 
                            : "text-amber-500"
                      }`} />
                      
                      {/* Interactive Button */}
                      <button
                        type="button"
                        onClick={() => {
                          const matchingPoint = damagePoints.find(d => d.partId === point.partId);
                          setActiveHotspot({
                            id: point.partId,
                            name: point.partName,
                            left: `${point.x}%`,
                            top: `${point.y}%`,
                          });
                          setPartNameInput(point.partName.toUpperCase());
                          setDamageType(matchingPoint ? matchingPoint.type : "riscado");
                          setDescription(matchingPoint ? (matchingPoint.description || "") : "");
                        }}
                        className={`h-5 w-5 rounded-full border-2 text-[8px] font-extrabold flex items-center justify-center shadow-lg transition-all duration-300 pointer-events-auto ${colorClass} ${
                          isActive ? "ring-4 ring-offset-2 ring-zinc-500 scale-120" : ""
                        }`}
                        title={point.partName}
                      >
                        {point.isPending ? "+" : point.type === "quebrado" ? "Q" : "R"}
                      </button>
                    </div>
                  );
                });
              })()}
            </div>
          </div>

          {/* 2D Popover Damage Edit Form Overlay */}
          {activeHotspot && (
            <div className="absolute z-40 bottom-2 left-2 right-2 bg-white/95 backdrop-blur-md border border-zinc-200 p-2 rounded-xl shadow-xl flex flex-col md:flex-row md:items-center gap-2 sm:gap-3 animate-fade-in text-zinc-800 shadow-zinc-200/50">
              <div className="flex-1">
                <div className="flex items-center gap-1.5">
                  <AlertCircle className="h-3 w-3 text-zinc-400" />
                  <p className="text-[9px] font-bold text-zinc-400 uppercase tracking-widest">
                    {readOnly ? "Avaria Registrada" : "Identificação da Avaria"} ({perspective.toUpperCase()})
                  </p>
                </div>
                {!readOnly ? (
                  <input
                    type="text"
                    value={partNameInput}
                    onChange={(e) => setPartNameInput(e.target.value.toUpperCase())}
                    placeholder="Nome da peça/área (ex: Paralama)"
                    className="w-full mt-1 bg-zinc-50 border border-zinc-200 focus:border-zinc-350 focus:bg-white rounded-md px-2 py-1 text-[11px] h-7 font-bold text-zinc-850 placeholder-zinc-400 focus:outline-none transition-all"
                  />
                ) : (
                  <h4 className="text-xs font-extrabold text-zinc-955 mt-0.5">{activeHotspot.name}</h4>
                )}
                
                {/* Mode Selectors */}
                {!readOnly && (
                  <div className="flex items-center gap-3 mt-1.5">
                    <label className="flex items-center gap-1 text-[10px] font-semibold cursor-pointer text-zinc-650">
                      <input
                        type="radio"
                        name="damageType2D"
                        checked={damageType === "riscado"}
                        onChange={() => setDamageType("riscado")}
                        className="accent-amber-500 h-3.5 w-3.5 cursor-pointer"
                      />
                      Riscado
                    </label>
                    <label className="flex items-center gap-1 text-[10px] font-semibold cursor-pointer text-zinc-650">
                      <input
                        type="radio"
                        name="damageType2D"
                        checked={damageType === "quebrado"}
                        onChange={() => setDamageType("quebrado")}
                        className="accent-red-500 h-3.5 w-3.5 cursor-pointer"
                      />
                      Quebrado
                    </label>
                  </div>
                )}

                {/* Read Only Details */}
                {readOnly && (
                  <div className="mt-1.5 text-[11px]">
                    {damagePoints.find(d => d.partId === activeHotspot.id) ? (
                      <div className="bg-zinc-50 border border-zinc-150 px-2 py-1 rounded-md flex flex-col gap-0.5 shadow-sm">
                        <span className="font-bold flex items-center gap-1.5 text-zinc-850">
                          <span className={`h-2 w-2 rounded-full ${
                            damagePoints.find(d => d.partId === activeHotspot.id)?.type === "quebrado" ? "bg-red-500 animate-pulse" : "bg-amber-500"
                          }`} />
                          Partição Registrada: {damagePoints.find(d => d.partId === activeHotspot.id)?.type === "quebrado" ? "Quebrado" : "Riscado"}
                        </span>
                        {damagePoints.find(d => d.partId === activeHotspot.id)?.description && (
                          <p className="text-[10px] text-zinc-500 italic">
                            "{damagePoints.find(d => d.partId === activeHotspot.id)?.description}"
                          </p>
                        )}
                      </div>
                    ) : (
                      <p className="text-zinc-500 font-medium italic">Partição intacta. Nenhuma avaria registrada nesta área.</p>
                    )}
                  </div>
                )}
              </div>

              {/* Description inputs */}
              {!readOnly ? (
                <div className="flex-[2] flex flex-col sm:flex-row items-stretch sm:items-center gap-1.5">
                  <input
                    type="text"
                    placeholder="Observação detalhada (ex: risco superficial de 3cm)"
                    value={description}
                    onChange={(e) => setDescription(e.target.value)}
                    className="flex-1 bg-zinc-50 border border-zinc-200 focus:border-zinc-350 focus:bg-white rounded-md px-2 py-1 h-7 text-[11px] text-zinc-800 placeholder-zinc-400 focus:outline-none transition-all"
                  />
                  <div className="flex gap-1.5 shrink-0">
                    <button
                      type="button"
                      onClick={handleSaveDamage}
                      className="bg-emerald-600 hover:bg-emerald-500 active:scale-95 text-white font-extrabold rounded-md px-2.5 py-1 h-7 text-[11px] transition-all shrink-0 cursor-pointer shadow-sm"
                    >
                      Confirmar
                    </button>
                    <button
                      type="button"
                      onClick={() => handleRemoveDamage(activeHotspot.id)}
                      className="bg-zinc-50 hover:bg-zinc-100 hover:text-red-600 active:scale-95 border border-zinc-200 text-zinc-650 font-bold rounded-md px-2.5 py-1 h-7 text-[11px] transition-all shrink-0 cursor-pointer"
                    >
                      Limpar
                    </button>
                    <button
                      type="button"
                      onClick={() => setActiveHotspot(null)}
                      className="bg-transparent hover:bg-zinc-50 active:scale-95 text-zinc-450 hover:text-zinc-600 rounded-md px-2 py-1 h-7 text-[11px] transition-all cursor-pointer"
                    >
                      Cancelar
                    </button>
                  </div>
                </div>
              ) : (
                <button
                  type="button"
                  onClick={() => setActiveHotspot(null)}
                  className="bg-zinc-50 hover:bg-zinc-100 text-zinc-700 font-bold rounded-md px-3 py-1 h-7 text-[11px] transition-colors cursor-pointer border border-zinc-200"
                >
                  Fechar Detalhes
                </button>
              )}
            </div>
          )}
        </div>
        ) : (
          <div className="lg:col-span-2 bg-zinc-50 border border-dashed border-zinc-200 rounded-2xl p-6 flex flex-col items-center justify-center text-center h-[360px] sm:h-[450px]">
            <div className="h-12 w-12 rounded-full bg-zinc-100 flex items-center justify-center mb-3">
              <Maximize2 className="h-6 w-6 text-zinc-400 animate-pulse" />
            </div>
            <p className="text-xs font-bold text-zinc-700">Mapeamento Aberto em Tela Cheia</p>
            <p className="text-[11px] text-zinc-400 mt-1 max-w-[200px]">
              Use a janela em tela cheia para registrar e visualizar avarias com zoom.
            </p>
            <button
              type="button"
              onClick={() => {
                setIsFullscreen(false);
                resetZoom();
              }}
              className="mt-4 bg-zinc-900 hover:bg-zinc-800 text-white font-bold text-xs rounded-xl px-4 py-2 transition-colors cursor-pointer shadow-sm"
            >
              Fechar Tela Cheia
            </button>
          </div>
        )}

        {/* Registered Damage List (Sidebar Panel) */}
        <div className="h-[450px] flex flex-col overflow-hidden print:border-none print:shadow-none print:p-0 print:overflow-visible">
          <h4 className="text-xs font-bold text-zinc-400 uppercase tracking-widest mb-3.5 flex items-center gap-1.5 border-b border-zinc-50 pb-2 print:text-zinc-500 print:border-zinc-100 print:mb-2">
            <span>Avarias Registradas ({damagePoints.length})</span>
          </h4>
          
          {damagePoints.length === 0 ? (
            <div className="flex-1 flex flex-col items-center justify-center text-center p-6 bg-zinc-50 rounded-2xl border border-dashed border-zinc-200 print:bg-transparent print:border-none print:p-2">
              <div className="h-10 w-10 rounded-full bg-emerald-50 text-emerald-600 flex items-center justify-center shadow-sm mb-3 print:bg-emerald-105 print:shadow-none print:mb-1.5">
                <CheckCircle2 className="h-6 w-6 animate-bounce print:animate-none" style={{ animationDuration: '3s' }} />
              </div>
              <p className="text-xs font-extrabold text-zinc-800 uppercase tracking-wider">Moto Intacta</p>
              <p className="text-[10px] text-zinc-400 font-semibold mt-1 max-w-[180px] leading-relaxed print:max-w-none">
                Nenhum sinal de dano ou avaria registrado nesta motocicleta.
              </p>
            </div>
          ) : (
            <div className="flex-1 overflow-y-auto space-y-2.5 pr-1.5 scrollbar-thin print:overflow-visible print:space-y-2">
              {damagePoints.map((point) => (
                <div
                  key={point.partId}
                  onClick={() => handleSelectDamageFromList(point.partId)}
                  className={`flex items-start justify-between p-3 rounded-xl border transition-all text-xs cursor-pointer print:break-inside-avoid ${
                    point.type === "riscado"
                      ? "bg-amber-50/40 border-amber-100 hover:bg-amber-50 hover:border-amber-200 shadow-sm print:bg-transparent print:border-zinc-200 print:p-2"
                      : "bg-red-50/40 border-red-100 hover:bg-red-50 hover:border-red-200 shadow-sm print:bg-transparent print:border-zinc-200 print:p-2"
                  }`}
                >
                  <div className="min-w-0 flex-1">
                    <div className="flex items-center gap-1.5 font-bold text-zinc-900 mb-0.5">
                      <span
                        className={`h-2.5 w-2.5 rounded-full shrink-0 shadow-sm print:shadow-none ${
                          point.type === "riscado" ? "bg-amber-500" : "bg-red-500 print:animate-none"
                        }`}
                      />
                      <span className="truncate">{point.partName}</span>
                    </div>
                    <p className="text-[10px] font-bold text-zinc-400 uppercase tracking-widest mb-1.5 print:mb-1">
                      {point.type === "riscado" ? "Riscado" : "Quebrado"}
                    </p>
                    {point.description ? (
                      <p className="text-[10px] text-zinc-650 bg-white/70 border border-zinc-150 px-2 py-1.5 rounded-lg italic leading-relaxed break-words print:bg-transparent print:border-none print:p-0 print:mt-1">
                        "{point.description}"
                      </p>
                    ) : (
                      <p className="text-[10px] text-zinc-400 italic font-medium px-2 py-0.5 print:px-0">Sem observações.</p>
                    )}

                    {/* Photo area — hidden on screen if no photo attached, shown in print if photo exists */}
                    {point.photo && (
                      <div className="mt-1.5">
                        {/* Print thumbnail */}
                        <img
                          src={point.photo}
                          alt={`Foto: ${point.partName}`}
                          className="hidden print:block w-16 h-16 object-cover rounded-lg border border-zinc-200 mt-1"
                        />
                        {/* Screen view button */}
                        <button
                          type="button"
                          onClick={(e) => {
                            e.stopPropagation();
                            setActiveLightboxPhoto(point.photo!);
                          }}
                          className="print:hidden flex items-center gap-1 text-[10px] font-bold text-zinc-500 hover:text-zinc-900 bg-zinc-50 hover:bg-zinc-100 border border-zinc-200 rounded-md px-2 py-0.5 transition-colors cursor-pointer"
                        >
                          <Eye className="h-3 w-3" />
                          Visualizar foto
                        </button>
                      </div>
                    )}

                    {/* Upload button (edit mode only, screen only) */}
                    {!readOnly && (
                      <div className="mt-1.5 print:hidden" onClick={(e) => e.stopPropagation()}>
                        <input
                          type="file"
                          accept="image/*"
                          id={`dmg-photo-${point.partId}`}
                          className="hidden"
                          onChange={(e) => {
                            const file = e.target.files?.[0];
                            if (file) {
                              const reader = new FileReader();
                              reader.onloadend = () => {
                                const updated = damagePoints.map(p =>
                                  p.partId === point.partId
                                    ? { ...p, photo: reader.result as string }
                                    : p
                                );
                                onChange(updated);
                                setActiveDropdown(null);
                              };
                              reader.readAsDataURL(file);
                            }
                            e.target.value = "";
                          }}
                        />
                        <div className="relative inline-block">
                          <button
                            type="button"
                            onClick={(e) => {
                              e.stopPropagation();
                              setActiveDropdown(activeDropdown === point.partId ? null : point.partId);
                            }}
                            onTouchStart={(e) => e.stopPropagation()}
                            onTouchEnd={(e) => e.stopPropagation()}
                            onTouchMove={(e) => e.stopPropagation()}
                            className={`flex items-center gap-1 text-[10px] font-bold rounded-md px-2 py-0.5 transition-colors cursor-pointer border ${
                              point.photo
                                ? "text-emerald-700 bg-emerald-50 border-emerald-200 hover:bg-emerald-100"
                                : "text-zinc-500 bg-zinc-50 border-zinc-200 hover:bg-zinc-100 hover:text-zinc-800"
                            }`}
                          >
                            <Camera className="h-3 w-3" />
                            {point.photo ? "Trocar foto" : "📸 Foto"}
                          </button>

                          {activeDropdown === point.partId && (
                            <>
                              <div
                                className="fixed inset-0 z-30"
                                onClick={(e) => {
                                  e.stopPropagation();
                                  setActiveDropdown(null);
                                }}
                                onTouchStart={(e) => e.stopPropagation()}
                                onTouchEnd={(e) => e.stopPropagation()}
                                onTouchMove={(e) => e.stopPropagation()}
                              />
                              <div 
                                className="absolute left-0 mt-1 bg-white border border-zinc-200 rounded-lg shadow-lg py-1 z-40 min-w-[130px] flex flex-col align-stretch"
                                onTouchStart={(e) => e.stopPropagation()}
                                onTouchEnd={(e) => e.stopPropagation()}
                                onTouchMove={(e) => e.stopPropagation()}
                              >
                                <button
                                  type="button"
                                  onClick={(e) => {
                                    e.stopPropagation();
                                    handleCapturePhoto(point.partId);
                                  }}
                                  className="w-full text-left px-3 py-1.5 text-[10px] font-bold text-zinc-700 hover:bg-zinc-50 flex items-center gap-1.5 cursor-pointer border-none bg-transparent"
                                >
                                  📷 Tirar Foto
                                </button>
                                <button
                                  type="button"
                                  onClick={(e) => {
                                    e.stopPropagation();
                                    document.getElementById(`dmg-photo-${point.partId}`)?.click();
                                  }}
                                  className="w-full text-left px-3 py-1.5 text-[10px] font-bold text-zinc-700 hover:bg-zinc-50 flex items-center gap-1.5 cursor-pointer border-none bg-transparent"
                                >
                                  📁 Escolher da Galeria
                                </button>
                              </div>
                            </>
                          )}
                        </div>
                        {point.photo && (
                          <button
                            type="button"
                            onClick={() => {
                              const updated = damagePoints.map(p =>
                                p.partId === point.partId ? { ...p, photo: undefined } : p
                              );
                              onChange(updated);
                            }}
                            className="ml-1 text-[10px] font-bold text-red-400 hover:text-red-600 transition-colors cursor-pointer"
                          >
                            ✕
                          </button>
                        )}
                      </div>
                    )}
                  </div>

                  {!readOnly && (
                    <button
                      type="button"
                      onClick={(e) => {
                        e.stopPropagation();
                        handleRemoveDamage(point.partId);
                      }}
                      className="text-zinc-300 hover:text-red-500 hover:bg-red-50/80 p-1.5 rounded-lg transition-all shrink-0 cursor-pointer ml-2"
                      title="Excluir avaria"
                    >
                      <Trash2 className="h-4 w-4" />
                    </button>
                  )}
                  {readOnly && (
                    <span className="text-zinc-350 hover:text-zinc-500 p-1 transition-colors shrink-0">
                      <ChevronRight className="h-4 w-4" />
                    </span>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>

    {/* Fullscreen Overlay Portal */}
    {isFullscreen && typeof document !== "undefined" && createPortal(
      <div className="fixed inset-0 z-[9999] bg-zinc-950/98 backdrop-blur-md flex flex-col p-4 select-none animate-fade-in text-white">
        
        {/* Header */}
        <div className="flex items-center justify-between pb-3 border-b border-zinc-800 shrink-0">
          <div>
            <h3 className="text-xs sm:text-sm font-bold text-white flex items-center gap-2">
              <Wrench className="h-4 w-4 text-zinc-400" />
              Mapeamento Visual de Avarias
            </h3>
            <p className="text-[10px] sm:text-xs text-zinc-400 mt-0.5">
              {readOnly 
                ? "Visualizando avarias registradas com suporte a zoom por gestos." 
                : "Clique na moto para registrar avaria. Use pinça com 2 dedos para dar zoom e 1 dedo para mover."}
            </p>
          </div>

          <button
            type="button"
            onClick={() => {
              setIsFullscreen(false);
              resetZoom();
            }}
            className="p-2 bg-zinc-900 border border-zinc-800 hover:bg-zinc-800 text-zinc-300 hover:text-white rounded-xl transition-all cursor-pointer shadow-sm"
            title="Fechar Tela Cheia"
          >
            <Minimize2 className="h-4.5 w-4.5" />
          </button>
        </div>

        {/* HUD overlay style inside fullscreen container */}
        <div className="flex-1 w-full relative overflow-hidden flex flex-col justify-between my-3 bg-zinc-900/50 border border-zinc-850 rounded-2xl">
          
          {/* Zoom HUD indicator */}
          {zoomLevel > 1 && (
            <div className="absolute top-16 right-3 z-40 flex items-center gap-1.5 animate-fade-in">
              <span className="text-[10px] font-extrabold text-zinc-300 bg-zinc-900/90 backdrop-blur-sm border border-zinc-850 px-2 py-0.5 rounded-md shadow-sm">
                {Math.round(zoomLevel * 100)}%
              </span>
              <button
                type="button"
                onClick={resetZoom}
                className="p-1 bg-zinc-900/90 backdrop-blur-sm border border-zinc-800 text-zinc-400 hover:text-white rounded-md shadow-sm cursor-pointer"
              >
                <RotateCcw className="h-3 w-3" />
              </button>
            </div>
          )}

          {/* Quick HUD controls overlay (Top Header Inside Canvas) */}
          <div className="absolute top-3 left-3 right-3 z-30 flex items-center justify-between pointer-events-none">
            {/* View presets */}
            <div className="flex gap-1 bg-zinc-900/90 backdrop-blur-sm border border-zinc-800 p-1 rounded-xl pointer-events-auto shadow-sm">
              {[
                { key: "left", label: "Esq" },
                { key: "right", label: "Dir" },
                { key: "front", label: "Front" },
                { key: "rear", label: "Tras" },
                { key: "top", label: "Topo" },
              ].map((view) => (
                <button
                  key={view.key}
                  type="button"
                  onClick={() => {
                    setPerspective(view.key as any);
                    setActiveHotspot(null);
                    resetZoom();
                  }}
                  className={`px-3 py-1 text-[11px] font-bold rounded-lg transition-all ${
                    perspective === view.key
                      ? "bg-white text-zinc-950 shadow-sm"
                      : "text-zinc-400 hover:text-white hover:bg-zinc-800"
                  }`}
                >
                  {view.label}
                </button>
              ))}
            </div>

            {/* Reset / back to default */}
            <button
              type="button"
              onClick={() => {
                setPerspective("left");
                setActiveHotspot(null);
                resetZoom();
              }}
              className="p-1.5 bg-zinc-900/90 backdrop-blur-sm border border-zinc-800 hover:border-zinc-700 text-zinc-400 hover:text-white rounded-xl transition-colors pointer-events-auto shadow-sm"
              title="Voltar ao Padrão (Esq)"
            >
              <RotateCcw className="h-4 w-4" />
            </button>
          </div>

          {/* Tutorial Tip */}
          <div className="absolute top-16 left-1/2 -translate-x-1/2 z-20 pointer-events-none text-center bg-zinc-900/70 border border-zinc-800 px-3.5 py-1 rounded-full text-[10px] font-bold text-zinc-400 tracking-wide backdrop-blur-[1px] opacity-80">
            {readOnly ? "Imagem Real da Moto (Zoom Habilitado)" : "Clique na foto para registrar a avaria no local exato"}
          </div>

          {/* 2D Schematic Interactive Area */}
          <div
            ref={zoomContainerRef}
            onTouchStart={(e) => {
              if (e.touches.length === 2) handlePinchStart(e);
              else if (e.touches.length === 1 && zoomLevel > 1) {
                lastPanPoint.current = { x: e.touches[0].clientX, y: e.touches[0].clientY };
              }
            }}
            onTouchMove={(e) => {
              if (e.touches.length >= 2 || (e.touches.length === 1 && zoomLevel > 1 && !isCalibrating)) {
                handlePinchMove(e);
              }
            }}
            onTouchEnd={handlePinchEnd}
            className="w-full h-full flex items-center justify-center p-4 rounded-2xl relative select-none bg-zinc-950"
          >
            {/* Real motorcycle image + Hotspots Overlay */}
            <div 
              onClick={handleContainerClick}
              onMouseDown={handleMouseDown}
              onMouseMove={handleMouseMove}
              onMouseUp={handleMouseUp}
              onMouseLeave={handleMouseLeave}
              onTouchStart={handleTouchStart}
              onTouchMove={handleTouchMove}
              onTouchEnd={handleTouchEnd}
              style={{
                position: "relative",
                width: "auto",
                height: "auto",
                maxWidth: "100%",
                maxHeight: "100%",
                aspectRatio: "2624/1632",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                cursor: readOnly ? "default" : "crosshair",
                touchAction: (isCalibrating || zoomLevel > 1) ? "none" : "auto",
                transform: `scale(${zoomLevel}) translate(${panOffset.x / zoomLevel}px, ${panOffset.y / zoomLevel}px)`,
                transformOrigin: "center center",
                transition: isPinching ? "none" : "transform 0.2s ease-out",
              }}
              className="text-zinc-100"
            >
              {renderMotorcycleImage()}

              {/* SVG overlay to render polygons during calibration or for debug */}
              <svg className="absolute inset-0 w-full h-full pointer-events-none z-20">
                {(calibrationData[perspective] || []).map((h, i) => {
                  if (!h.polygon || h.polygon.length < 2) return null;
                  const pointsString = h.polygon.map(p => `${p.x}%,${p.y}%`).join(" ");
                  const isActive = i === calibrationActiveIndex && isCalibrating;
                  return (
                    <polygon
                      key={h.id}
                      points={pointsString}
                      fill={isActive ? "rgba(168, 85, 247, 0.25)" : "rgba(168, 85, 247, 0.08)"}
                      stroke={isActive ? "#a855f7" : "rgba(168, 85, 247, 0.4)"}
                      strokeWidth="1.5"
                    />
                  );
                })}

                {isCalibrating && currentPath.length > 0 && (
                  <>
                    {currentPath.length >= 3 ? (
                      <polygon
                        points={currentPath.map(p => `${p.x}%,${p.y}%`).join(" ")}
                        fill="rgba(168, 85, 247, 0.15)"
                        stroke="#a855f7"
                        strokeWidth="2"
                        strokeDasharray="4 4"
                      />
                    ) : (
                      <polyline
                        points={currentPath.map(p => `${p.x}%,${p.y}%`).join(" ")}
                        fill="none"
                        stroke="#a855f7"
                        strokeWidth="2"
                        strokeDasharray="4 4"
                      />
                    )}
                    {(!hasDragged || currentPath.length < 15) && currentPath.map((pt, idx) => (
                      <circle
                        key={idx}
                        cx={`${pt.x}%`}
                        cy={`${pt.y}%`}
                        r="3.5"
                        fill="#a855f7"
                        stroke="#fff"
                        strokeWidth="1"
                      />
                    ))}
                  </>
                )}
              </svg>

              {/* Calibration pins if active */}
              {isCalibrating && (calibrationData[perspective] || []).map((h, i) => {
                let xVal = 0;
                let yVal = 0;
                if (h.polygon && h.polygon.length > 0) {
                  const ctr = getPolygonCentroid(h.polygon);
                  if (ctr) {
                    xVal = ctr.x;
                    yVal = ctr.y;
                  }
                } else if (h.left && h.top) {
                  xVal = parseFloat(h.left);
                  yVal = parseFloat(h.top);
                } else {
                  return null;
                }
                const isActive = i === calibrationActiveIndex;
                return (
                  <div
                    key={h.id}
                    style={{ top: `${yVal}%`, left: `${xVal}%` }}
                    className="absolute -translate-x-1/2 -translate-y-1/2 z-20 pointer-events-none"
                  >
                    <div className={`h-4 w-4 rounded-full flex items-center justify-center text-[8px] font-bold text-white shadow ${
                      isActive ? "bg-purple-600 ring-2 ring-purple-300 scale-125" : "bg-purple-400 opacity-60"
                    }`}>
                      {i + 1}
                    </div>
                  </div>
                );
              })}

              {/* Clickable 2D Hotspots Overlay */}
              {(() => {
                const pendingPoint = activeHotspot && !damagePoints.some(d => d.partId === activeHotspot.id) ? {
                  partId: activeHotspot.id,
                  partName: partNameInput || activeHotspot.name,
                  type: damageType,
                  description: description,
                  x: activeHotspot.left ? parseFloat(activeHotspot.left) : 0,
                  y: activeHotspot.top ? parseFloat(activeHotspot.top) : 0,
                  perspective: perspective,
                  isPending: true
                } : null;

                const displayPoints = damagePoints
                  .map(p => {
                    const info = getPointDisplayInfo(p);
                    if (!info) return null;
                    return {
                      ...p,
                      x: info.x,
                      y: info.y,
                      perspective: info.perspective,
                      isPending: false
                    };
                  })
                  .filter((p): p is NonNullable<typeof p> => p !== null && p.perspective === perspective);

                if (pendingPoint) {
                  displayPoints.push(pendingPoint as any);
                }

                return displayPoints.map((point) => {
                  const isActive = activeHotspot?.id === point.partId;
                  let colorClass = "bg-blue-500 border-blue-200 text-white shadow-blue-500/50 hover:bg-blue-600 hover:scale-110";
                  let animationClass = "";

                  if (point.isPending) {
                    colorClass = "bg-zinc-650 border-zinc-450 text-white shadow-zinc-500/50 hover:scale-110 animate-pulse";
                    animationClass = "animate-ping";
                  } else if (point.type === "quebrado") {
                    colorClass = "bg-red-500 border-red-300 text-white shadow-red-500/80 hover:bg-red-600 animate-pulse scale-110";
                    animationClass = "animate-ping";
                  } else if (point.type === "riscado") {
                    colorClass = "bg-amber-500 border-amber-300 text-white shadow-amber-500/80 hover:bg-amber-600 hover:scale-110 scale-105";
                    animationClass = "animate-pulse";
                  }

                  return (
                    <div
                      key={point.partId}
                      style={{ top: `${point.y}%`, left: `${point.x}%` }}
                      className="absolute -translate-x-1/2 -translate-y-1/2 z-10 animate-fade-in"
                    >
                      <div className={`absolute -inset-2.5 rounded-full border border-current opacity-40 pointer-events-none scale-100 ${animationClass} ${
                        point.isPending ? "text-zinc-500" : point.type === "quebrado" ? "text-red-500" : "text-amber-500"
                      }`} />
                      
                      <button
                        type="button"
                        onClick={() => {
                          const matchingPoint = damagePoints.find(d => d.partId === point.partId);
                          setActiveHotspot({
                            id: point.partId,
                            name: point.partName,
                            left: `${point.x}%`,
                            top: `${point.y}%`,
                          });
                          setPartNameInput(point.partName.toUpperCase());
                          setDamageType(matchingPoint ? matchingPoint.type : "riscado");
                          setDescription(matchingPoint ? (matchingPoint.description || "") : "");
                        }}
                        className={`h-5 w-5 rounded-full border-2 text-[8px] font-extrabold flex items-center justify-center shadow-lg transition-all duration-300 pointer-events-auto ${colorClass} ${
                          isActive ? "ring-4 ring-offset-2 ring-white scale-120" : ""
                        }`}
                        title={point.partName}
                      >
                        {point.isPending ? "+" : point.type === "quebrado" ? "Q" : "R"}
                      </button>
                    </div>
                  );
                });
              })()}
            </div>
          </div>

          {/* 2D Popover Damage Edit Form Overlay */}
          {activeHotspot && (
            <div className="absolute z-40 bottom-2 left-2 right-2 bg-white border border-zinc-200 p-2.5 rounded-xl shadow-2xl flex flex-col md:flex-row md:items-center gap-2 sm:gap-3 animate-fade-in text-zinc-800">
              <div className="flex-1">
                <div className="flex items-center gap-1.5">
                  <AlertCircle className="h-3 w-3 text-zinc-400" />
                  <p className="text-[9px] font-bold text-zinc-400 uppercase tracking-widest">
                    {readOnly ? "Avaria Registrada" : "Identificação da Avaria"} ({perspective.toUpperCase()})
                  </p>
                </div>
                {!readOnly ? (
                  <input
                    type="text"
                    value={partNameInput}
                    onChange={(e) => setPartNameInput(e.target.value.toUpperCase())}
                    placeholder="Nome da peça/área (ex: Paralama)"
                    className="w-full mt-1 bg-zinc-50 border border-zinc-200 focus:border-zinc-350 focus:bg-white rounded-md px-2 py-1 text-[11px] h-7 font-bold text-zinc-850 placeholder-zinc-400 focus:outline-none transition-all"
                  />
                ) : (
                  <h4 className="text-xs font-extrabold text-zinc-955 mt-0.5">{activeHotspot.name}</h4>
                )}
                
                {!readOnly && (
                  <div className="flex items-center gap-3 mt-1.5">
                    <label className="flex items-center gap-1 text-[10px] font-semibold cursor-pointer text-zinc-650">
                      <input
                        type="radio"
                        name="damageType2D"
                        checked={damageType === "riscado"}
                        onChange={() => setDamageType("riscado")}
                        className="accent-amber-500 h-3.5 w-3.5 cursor-pointer"
                      />
                      Riscado
                    </label>
                    <label className="flex items-center gap-1 text-[10px] font-semibold cursor-pointer text-zinc-650">
                      <input
                        type="radio"
                        name="damageType2D"
                        checked={damageType === "quebrado"}
                        onChange={() => setDamageType("quebrado")}
                        className="accent-red-500 h-3.5 w-3.5 cursor-pointer"
                      />
                      Quebrado
                    </label>
                  </div>
                )}

                {readOnly && (
                  <div className="mt-1.5 text-[11px]">
                    {damagePoints.find(d => d.partId === activeHotspot.id) ? (
                      <div className="bg-zinc-50 border border-zinc-150 px-2 py-1 rounded-md flex flex-col gap-0.5 shadow-sm">
                        <span className="font-bold flex items-center gap-1.5 text-zinc-850">
                          <span className={`h-2 w-2 rounded-full ${
                            damagePoints.find(d => d.partId === activeHotspot.id)?.type === "quebrado" ? "bg-red-500 animate-pulse" : "bg-amber-500"
                          }`} />
                          Partição Registrada: {damagePoints.find(d => d.partId === activeHotspot.id)?.type === "quebrado" ? "Quebrado" : "Riscado"}
                        </span>
                        {damagePoints.find(d => d.partId === activeHotspot.id)?.description && (
                          <p className="text-[10px] text-zinc-500 italic">
                            "{damagePoints.find(d => d.partId === activeHotspot.id)?.description}"
                          </p>
                        )}
                      </div>
                    ) : (
                      <p className="text-zinc-500 font-medium italic">Partição intacta. Nenhuma avaria registrada nesta área.</p>
                    )}
                  </div>
                )}
              </div>

              {!readOnly ? (
                <div className="flex-[2] flex flex-col sm:flex-row items-stretch sm:items-center gap-1.5">
                  <input
                    type="text"
                    placeholder="Observação detalhada (ex: risco superficial de 3cm)"
                    value={description}
                    onChange={(e) => setDescription(e.target.value)}
                    className="flex-1 bg-zinc-50 border border-zinc-200 focus:border-zinc-350 focus:bg-white rounded-md px-2 py-1 h-7 text-[11px] text-zinc-800 placeholder-zinc-400 focus:outline-none transition-all"
                  />
                  <div className="flex gap-1.5 shrink-0">
                    <button
                      type="button"
                      onClick={handleSaveDamage}
                      className="bg-emerald-600 hover:bg-emerald-500 active:scale-95 text-white font-extrabold rounded-md px-2.5 py-1 h-7 text-[11px] transition-all shrink-0 cursor-pointer shadow-sm"
                    >
                      Confirmar
                    </button>
                    <button
                      type="button"
                      onClick={() => handleRemoveDamage(activeHotspot.id)}
                      className="bg-zinc-50 hover:bg-zinc-100 hover:text-red-600 active:scale-95 border border-zinc-200 text-zinc-650 font-bold rounded-md px-2.5 py-1 h-7 text-[11px] transition-all shrink-0 cursor-pointer"
                    >
                      Limpar
                    </button>
                    <button
                      type="button"
                      onClick={() => setActiveHotspot(null)}
                      className="bg-transparent hover:bg-zinc-50 active:scale-95 text-zinc-450 hover:text-zinc-650 rounded-md px-2 py-1 h-7 text-[11px] transition-all cursor-pointer"
                    >
                      Cancelar
                    </button>
                  </div>
                </div>
              ) : (
                <button
                  type="button"
                  onClick={() => setActiveHotspot(null)}
                  className="bg-zinc-50 hover:bg-zinc-100 text-zinc-700 font-bold rounded-md px-3 py-1 h-7 text-[11px] transition-colors cursor-pointer border border-zinc-200"
                >
                  Fechar Detalhes
                </button>
              )}
            </div>
          )}
        </div>
      </div>,
      document.body
    )}

    {/* Lightbox for damage point photo */}
    {activeLightboxPhoto && typeof document !== "undefined" && createPortal(
      <div
        className="fixed inset-0 z-[9999] bg-black/90 flex items-center justify-center p-4"
        onClick={() => setActiveLightboxPhoto(null)}
      >
        <button
          type="button"
          className="absolute top-4 right-4 text-white bg-white/20 hover:bg-white/30 rounded-full p-2 transition-colors cursor-pointer"
          onClick={() => setActiveLightboxPhoto(null)}
        >
          <X className="h-5 w-5" />
        </button>
        <img
          src={activeLightboxPhoto}
          alt="Foto da avaria"
          className="max-w-full max-h-full object-contain rounded-xl shadow-2xl"
          onClick={(e) => e.stopPropagation()}
        />
      </div>,
      document.body
    )}
    </>
  );
}
